function p = reference_trajectory(p)
% Reference trajectory definitions — Crazyflie 2.1 indoor scale
%
% XY velocity and acceleration references are generated by a proportional
% cascade on the current state (matching the SMC reference structure):
%   xd_dot  = kpx * (xd - x_pos)      position error -> velocity ref
%   xd_ddot = kdx * (xd_dot - x_dot)  velocity error -> accel ref
%
% Only x_des(t), y_des(t) are defined here (anonymous fn of t).
% z_des, psi_des and their analytical derivatives are also defined here.
%
% SCALE RATIONALE
% ───────────────
% Original trajectory: 2 m radius, z = 5 m
% CF2.1 is an indoor nano-quad; realistic indoor envelope:
%   - Position amplitude: 0.3 – 0.5 m
%   - Altitude:           0.5 – 1.0 m
%   - Max speed:          < 0.5 m/s
% The active trajectory (Slow Circle) uses r = 0.5 m, z = 0.5 m.
% Max centripetal accel = r*omega^2 = 0.045 m/s^2 => phi_des ≈ 0.26 deg.
%
% ── HOW TO SWITCH TRAJECTORY ────────────────────────────────────────
%   1. Comment out the currently ACTIVE block.
%   2. Uncomment the block you want.
%   Only ONE block should be active at a time.
%
% ── AVAILABLE TRAJECTORIES ──────────────────────────────────────────
%   1. Slow Circle  (indoor scale, r=0.5 m)              [ACTIVE]
%   2. Hover        (step to fixed point)
%   3. Lissajous Figure-8  (original structure, scaled down)
%   4. Helix        (slow climb)
% ────────────────────────────────────────────────────────────────────


% ════════════════════════════════════════════════════════════════════
% TRAJECTORY 1: Slow Circle — indoor scale  [ACTIVE]
%
%   xd(t) = r * cos(omega*t)
%   yd(t) = r * sin(omega*t)
%   zd    = 0.5 m  (constant hover altitude)
%   psi   = 0      (fixed heading)
%
%   r = 0.5 m, omega = 0.3 rad/s  =>  period ≈ 21 s, v_max = 0.15 m/s
%   Centripetal accel = r*omega^2 = 0.045 m/s^2  =>  phi_des ≈ 0.26 deg
% ════════════════════════════════════════════════════════════════════
    % r     = 0.5;    % radius (m)
    % omega = 0.3;    % angular rate (rad/s)
    % z0    = 0.5;    % hover altitude (m)
    % 
    % p.x_des = @(t)  r * cos(omega * t);
    % p.y_des = @(t)  r * sin(omega * t);
    % 
    % p.z_des         = @(t)  z0 + 0*t;
    % p.zd_dot_des    = @(t)  0 * t;
    % p.zd_ddot_des   = @(t)  0 * t;
    % 
    % p.psi_des       = @(t)  0 * t;
    % p.psid_dot_des  = @(t)  0 * t;
    % p.psid_ddot_des = @(t)  0 * t;


% ════════════════════════════════════════════════════════════════════
% TRAJECTORY 2: Hover — step to fixed point
%
%   xd = 0.3,  yd = 0,  zd = 0.5,  psi = 0
%   Use this first to verify hover stability before switching to dynamic traj.
% ════════════════════════════════════════════════════════════════════
    % p.x_des = @(t)  0.3 + 0*t;
    % p.y_des = @(t)  0   + 0*t;
    %
    % p.z_des         = @(t)  0.5 + 0*t;
    % p.zd_dot_des    = @(t)  0 * t;
    % p.zd_ddot_des   = @(t)  0 * t;
    %
    % p.psi_des       = @(t)  0 * t;
    % p.psid_dot_des  = @(t)  0 * t;
    % p.psid_ddot_des = @(t)  0 * t;


% ════════════════════════════════════════════════════════════════════
% TRAJECTORY 3: Lissajous Figure-8 (indoor scale)
%
%   xd(t) = Ax * cos(omega*t)
%   yd(t) = Ay * sin(2*omega*t)   (2:1 frequency ratio => figure-8)
%   zd    = 0.5 m  (constant)
%   Ax = Ay = 0.4 m,  omega = 0.1 rad/s  =>  v_max ≈ 0.08 m/s
% ════════════════════════════════════════════════════════════════════
    % Ax = 0.4;   Ay = 0.4;   omega_f = 0.2;
    % 
    % p.x_des = @(t)  Ax * cos(omega_f * t);
    % p.y_des = @(t)  Ay * sin(2 * omega_f * t);
    % 
    % p.z_des         = @(t)  0.5 + 0*t;
    % p.zd_dot_des    = @(t)  0 * t;
    % p.zd_ddot_des   = @(t)  0 * t;
    % 
    % p.psi_des       = @(t)  0 * t;
    % p.psid_dot_des  = @(t)  0 * t;
    % p.psid_ddot_des = @(t)  0 * t;

    Ax = 0.4;   Ay = 0.4;   omega_f = 0.2;

    p.x_des = @(t)  Ax * sin(2 * omega_f * t);
    p.y_des = @(t)  Ay * sin(omega_f * t);

    p.z_des         = @(t)  0.5 + ones(size(t));
    p.zd_dot_des    = @(t)  zeros(size(t));
    p.zd_ddot_des   = @(t)  zeros(size(t));

    p.psi_des       = @(t)  0 * t;
    p.psid_dot_des  = @(t)  0 * t;
    p.psid_ddot_des = @(t)  0 * t;


% ════════════════════════════════════════════════════════════════════
% TRAJECTORY 4: Helix (indoor, slow climb)
%
%   xd(t) = r * cos(omega*t)
%   yd(t) = r * sin(omega*t)
%   zd(t) = z0 + vz*t        (slow climb)
%   r = 0.4 m, omega = 0.3 rad/s, vz = 0.02 m/s
% ════════════════════════════════════════════════════════════════════
    % r_h   = 0.4;
    % om_h  = 0.3;
    % z0_h  = 0.3;
    % vz_h  = 0.02;
    %
    % p.x_des = @(t)  r_h * cos(om_h * t);
    % p.y_des = @(t)  r_h * sin(om_h * t);
    %
    % p.z_des         = @(t)  z0_h + vz_h * t;
    % p.zd_dot_des    = @(t)  vz_h + 0*t;
    % p.zd_ddot_des   = @(t)  0 * t;
    %
    % p.psi_des       = @(t)  0 * t;
    % p.psid_dot_des  = @(t)  0 * t;
    % p.psid_ddot_des = @(t)  0 * t;

end